window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[237]={"id":"237","numero":237,"titre":"Palpitations","objectifs":[{"id":"237-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des palpitations","contenu":"<p>Les <span class=\"kw-def\">palpitations</span> sont une <strong>perception anormale</strong> d'un rythme ou de\n      battements cardiaques <strong>normaux ou anormaux</strong> — la sensation d'un « cœur qui se débat » dans la\n      poitrine. Le patient décrit un cœur qui <span class=\"kw-clinique\">bat trop fort</span>, <span class=\"kw-clinique\">trop\n      vite</span> ou de façon <span class=\"kw-clinique\">irrégulière</span>.</p>\n\n      <p>C'est un <strong>trouble subjectif</strong>, témoignant <strong>ou non</strong> d'une anomalie cardiaque\n      sous-jacente, et le plus souvent <span class=\"kw-clinique\">anxiogène</span>. La <strong>localisation</strong> ressentie\n      n'est <span class=\"kw-alerte\">pas spécifique</span> et varie d'un patient à l'autre :</p>\n      <ul>\n        <li>région <span class=\"kw-clinique\">latérocervicale</span>, le long des axes carotidiens ;</li>\n        <li><span class=\"kw-clinique\">précordium</span> ;</li>\n        <li>région <span class=\"kw-clinique\">latérothoracique</span> ;</li>\n        <li>région <span class=\"kw-clinique\">médiothoracique</span>.</li>\n      </ul>\n\n      <p>Quatre <strong>familles de <span class=\"kw-clinique\">palpitations</span></strong> sont à connaître : la <span class=\"kw-etio\">fibrillation\n      atriale</span> et le <span class=\"kw-etio\">flutter atrial</span>, les <span class=\"kw-etio\">tachycardies\n      jonctionnelles</span>, et les <span class=\"kw-etio\">autres troubles du rythme</span>. Retenir que la\n      <strong>FA est la seule cause de <span class=\"kw-clinique\">tachycardie</span> réellement <span class=\"kw-alerte\">irrégulière</span></strong> — le\n      <span class=\"kw-etio\">flutter atrial</span>, lui, est le plus souvent <strong>régulier</strong>.</p>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/237/schema-4-familles-palpitations.png\" alt=\"Schéma des 4 familles de palpitations : fibrillation atriale et flutter atrial (irréguliers), tachycardies supraventriculaire et jonctionnelle\" loading=\"lazy\">\n        <figcaption>Les 4 familles de <span class=\"kw-clinique\">palpitations</span>. <strong>FA et <span class=\"kw-etio\">flutter atrial</span></strong> = origine atriale, FA irrégulière. <strong><span class=\"kw-clinique\">Tachycardie</span> jonctionnelle</strong> = cœur sain, patient jeune, apparition et fin brutales, <span class=\"kw-clinique\">polyurie</span> post-crise. Source : fiche source EDN item 237.</figcaption>\n      </figure>","frequence":0},{"id":"237-2","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes de gravité et diagnostiques ECG urgents","contenu":"<p>Devant des <span class=\"kw-clinique\">palpitations</span>, trois plans permettent de repérer une situation à risque : l'<strong>anamnèse</strong>,\n      les <strong>signes cliniques</strong> de mauvaise tolérance, et l'<strong><span class=\"kw-bio\">ECG</span></strong>. L'enjeu est de ne pas\n      méconnaître un trouble du rythme menaçant le <span class=\"kw-alerte\">pronostic vital</span>.</p>\n\n      <p><strong>Anamnèse alarmante</strong> :</p>\n      <ul>\n        <li><strong>ATCD personnels</strong> : <span class=\"kw-etio\">infarctus du myocarde</span>,\n        <span class=\"kw-etio\">HTA</span>, autre <span class=\"kw-etio\">cardiopathie</span>, trouble du rythme connu,\n        appareillage par <span class=\"kw-ttt\">stimulateur</span> ou <span class=\"kw-ttt\">défibrillateur</span> ;</li>\n        <li><strong>ATCD familiaux</strong> : <span class=\"kw-alerte\">mort subite</span>, surtout chez l'enfant ou\n        l'adolescent (avant <span class=\"kw-chiffre\">35 ans</span>) — fait évoquer une cause <span class=\"kw-etio\">génétique</span>\n        (<span class=\"kw-def\">syndrome de Brugada</span>, <span class=\"kw-def\">QT long</span>, <span class=\"kw-def\">dysplasie\n        arythmogène du ventricule droit</span>) et impose un <strong>arbre généalogique</strong> ;</li>\n        <li>prise d'un <span class=\"kw-ttt\">antiarythmique</span> ou d'un <span class=\"kw-ci\">traitement allongeant le\n        QT</span>.</li>\n      </ul>\n\n      <p><strong>Signes cliniques de gravité</strong> — ils traduisent une mauvaise tolérance hémodynamique, avec\n      baisse du débit cardiaque ou complication de l'<span class=\"kw-clinique\">arythmie</span> :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">FC &gt; 150 bpm</span> ;</li>\n        <li><span class=\"kw-alerte\">hypotension artérielle</span> ;</li>\n        <li>signes d'<span class=\"kw-alerte\">hypoperfusion périphérique</span> : <span class=\"kw-clinique\">TRC allongé</span>,\n        <span class=\"kw-clinique\">marbrures</span> ;</li>\n        <li><span class=\"kw-clinique\">angor</span> (parfois fonctionnel, surtout si <span class=\"kw-chiffre\">FC &gt; 200 bpm</span>) ;</li>\n        <li>signes d'<span class=\"kw-clinique\">insuffisance cardiaque</span> (<span class=\"kw-clinique\">dyspnée</span>) ;</li>\n        <li><span class=\"kw-alerte\">signes neurologiques déficitaires</span> évoquant un <span class=\"kw-clinique\">infarctus</span> cérébral (embolie sur FA) ;</li>\n        <li><span class=\"kw-alerte\">trouble de conscience</span> ;</li>\n        <li><span class=\"kw-clinique\">syncope</span> ou <span class=\"kw-clinique\">lipothymie</span>.</li>\n      </ul>\n\n      <p><strong><span class=\"kw-bio\">ECG</span></strong> — l'<span class=\"kw-bio\">ECG</span> initial est <strong>le plus souvent normal</strong> mais doit être réalisé\n      systématiquement ; l'objectif est surtout d'obtenir un <span class=\"kw-imagerie\">ECG en crise</span>. Sont des\n      <strong>urgences</strong> :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">tachycardie régulière à QRS large</span> = <strong><span class=\"kw-alerte\">TV</span> jusqu'à preuve du\n        contraire</strong>, imposant de se préparer à réanimer ;</li>\n        <li><span class=\"kw-alerte\">anomalie de repolarisation</span> faisant craindre un <span class=\"kw-etio\">SCA</span>\n        (surtout si « gêne » thoracique — mais peut correspondre à un <span class=\"kw-clinique\">angor</span> fonctionnel) ;</li>\n        <li><span class=\"kw-alerte\">BAV du 2ᵉ ou 3ᵉ degré</span> ;</li>\n        <li><span class=\"kw-alerte\">tachycardie à QRS fins &gt; 150 bpm</span> associée à des signes cliniques de gravité.</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> Une <span class=\"kw-clinique\">tachycardie</span> régulière à <span class=\"kw-alerte\">QRS large</span> est une\n        <strong><span class=\"kw-alerte\">TV</span> jusqu'à preuve du contraire</strong>. En cas de <span class=\"kw-alerte\">mauvaise tolérance\n        hémodynamique</span>, le traitement est la <span class=\"kw-ttt\">cardioversion électrique externe</span> en urgence.\n      </div>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/237/ecg-tachycardie-ventriculaire.png\" alt=\"ECG 12 dérivations d'une tachycardie ventriculaire avec dissociation atrio-ventriculaire et complexe de fusion\" loading=\"lazy\">\n        <figcaption><strong><span class=\"kw-clinique\">Tachycardie</span> ventriculaire</strong> : <span class=\"kw-clinique\">tachycardie</span> régulière à QRS larges, <strong>dissociation atrio-ventriculaire</strong> (aucune onde P n'est suivie d'un QRS — il n'y a pas de complexe P-QRS-T cohérent), présence possible d'un <strong>complexe de fusion</strong>. Source : fiche source EDN item 237.</figcaption>\n      </figure>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/237/schema-demarche-diagnostique-tachycardie.png\" alt=\"Schéma de la démarche diagnostique devant une tachycardie selon la régularité et la largeur des QRS\" loading=\"lazy\">\n        <figcaption>Démarche diagnostique devant une <span class=\"kw-clinique\">tachycardie</span>. <strong>Irrégulière</strong> (QRS fins ou larges) → <span class=\"kw-etio\">fibrillation atriale</span>. <strong>Régulière à QRS fins</strong> → <span class=\"kw-clinique\">tachycardie</span> sinusale, atriale (<span class=\"kw-clinique\">flutter</span>, <span class=\"kw-clinique\">tachycardie</span> atriale focale) ou jonctionnelle. <strong>Régulière à QRS larges</strong> → TV (le plus souvent) ou TSV avec bloc de branche / préexcitation. Source : fiche source EDN item 237.</figcaption>\n      </figure>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 342 — <span class=\"kw-clinique\">Malaise</span></em></p>","frequence":1},{"id":"237-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la notion de parallélisme électro-clinique","contenu":"<p>Le <span class=\"kw-def\">parallélisme électro-clinique</span> (ou <strong>corrélation\n      électro-clinique</strong>) désigne la <strong>concordance entre les symptômes</strong> ressentis par le patient\n      (les <span class=\"kw-clinique\">palpitations</span>) <strong>et les anomalies enregistrées sur l'<span class=\"kw-bio\">ECG</span></strong>. Poser le diagnostic d'un trouble du\n      rythme suppose d'obtenir un <span class=\"kw-imagerie\">ECG percritique</span> — c'est-à-dire <strong>concomitant à la\n      crise</strong>.</p>\n\n      <p>Plus la <strong>durée d'enregistrement</strong> est longue, plus la <span class=\"kw-bio\">sensibilité</span> de\n      détection est élevée :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">ECG 12 dérivations</span> de repos : <span class=\"kw-chiffre\">~10 secondes</span> seulement ;</li>\n        <li><span class=\"kw-imagerie\">Holter ECG</span> : <span class=\"kw-chiffre\">24 à 96 h</span> ;</li>\n        <li><span class=\"kw-imagerie\">Holter implantable</span> : <span class=\"kw-def\">surveillance</span> de <span class=\"kw-chiffre\">3 à 5 ans</span>.</li>\n      </ul>\n\n      <p>En crise, on peut <strong>orienter le diagnostic</strong> en intensifiant le filtre du\n      <span class=\"kw-def\">nœud atrio-ventriculaire</span> (NAV) : <span class=\"kw-ttt\">manœuvres vagales</span> puis\n      <span class=\"kw-ttt\">adénosine</span> en flash IV (ATP). Bloquer le NAV ralentit la cadence ventriculaire et\n      <strong>démasque l'activité atriale</strong>. L'effet observé oriente l'étiologie :</p>\n\n      <table >\n        <thead>\n          <tr><th>Effet du blocage du NAV</th><th>Interprétation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Interruption brutale</strong> de la <span class=\"kw-clinique\">tachycardie</span></td>\n            <td>Très en faveur d'une <span class=\"kw-etio\">tachycardie jonctionnelle</span> (réentrée intranodale ou voie accessoire)</td>\n          </tr>\n          <tr>\n            <td><strong>Ralentissement</strong> avec démasquage de l'activité atriale</td>\n            <td>Très en faveur d'une <span class=\"kw-etio\">TSV</span> :<br>\n              <strong>Ondes F :</strong> aspect en <span class=\"kw-radio\">toit d'usine</span> → <span class=\"kw-etio\">flutter atrial</span><br>\n              <strong><span class=\"kw-radio\">Trémulation de la ligne de base</span> :</strong> anarchique → <span class=\"kw-etio\">fibrillation atriale</span><br>\n              <strong>Ondes P' :</strong> avec retour à la ligne isoélectrique → <span class=\"kw-etio\">tachycardie atriale focale</span></td>\n          </tr>\n          <tr>\n            <td><strong>Aucun effet</strong> sur la fréquence ventriculaire</td>\n            <td>Très en faveur d'une <span class=\"kw-alerte\">tachycardie ventriculaire</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-ci\">Contre-indications</span> des manœuvres de blocage du NAV.</strong> La <span class=\"kw-ttt\">compression\n        carotidienne</span> est <span class=\"kw-ci\">contre-indiquée</span> en cas d'<span class=\"kw-ci\">athérome carotidien</span> ou de souffle.\n        L'<span class=\"kw-ttt\">adénosine</span> est <span class=\"kw-ci\">contre-indiquée</span> en cas d'<span class=\"kw-ci\">asthme</span> (risque de\n        bronchospasme intense, même chez un non-asthmatique) et d'<span class=\"kw-ci\">HTA ou hypotension non\n        contrôlée</span>. La compression oculaire bilatérale n'est <strong>plus recommandée</strong> (risque de\n        décollement de rétine).\n      </div>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/237/schema-raisonnement-tachycardie.png\" alt=\"Schéma du raisonnement devant une tachycardie : effet de l'inhibition du NAV par manœuvres vagales et adénosine\" loading=\"lazy\">\n        <figcaption>Raisonnement devant une <span class=\"kw-clinique\">tachycardie</span>. L'<strong>inhibition du NAV</strong> (manœuvres vagales, Striadyne/adénosine) produit un effet diagnostique : <strong>ralentissement</strong> → <span class=\"kw-clinique\">tachycardie</span> supraventriculaire ; <strong><span class=\"kw-ttt\">réduction</span></strong> → <span class=\"kw-clinique\">tachycardie</span> jonctionnelle ; <strong>aucun effet</strong> → <span class=\"kw-clinique\">tachycardie</span> ventriculaire. Source : fiche source EDN item 237.</figcaption>\n      </figure>","frequence":2},{"id":"237-4","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les modalités de réalisation des examens complémentaires de la prise en charge initiale","contenu":"<p>La prise en charge initiale repose sur un <strong>bilan systématique</strong>, puis sur des examens\n      orientés selon le contexte. L'objectif majeur reste d'établir le <span class=\"kw-def\">parallélisme\n      électro-clinique</span> en capturant un <span class=\"kw-bio\">ECG</span> percritique.</p>\n\n      <p><strong>Bilan systématique</strong> :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Biologie de routine</span> : <span class=\"kw-bio\">NFS</span>,\n        <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">alcoolémie</span>, <span class=\"kw-bio\">β-hCG</span>,\n        <span class=\"kw-bio\">TSH</span> — complétée selon le contexte ;</li>\n        <li><span class=\"kw-imagerie\">échocardiographie transthoracique (ETT)</span> : <strong>systématique</strong>, à la\n        recherche d'une <span class=\"kw-etio\">cardiopathie sous-jacente</span> ;</li>\n        <li><span class=\"kw-imagerie\">ECG 12 dérivations de repos</span> : la corrélation électro-clinique y est rarement\n        obtenue, mais des signes peuvent orienter — <span class=\"kw-clinique\">ESA</span> → rechercher FA, <span class=\"kw-clinique\">flutter</span>,\n        <span class=\"kw-clinique\">tachycardie</span> atriale ; <span class=\"kw-clinique\">ESV</span> → rechercher une <span class=\"kw-alerte\">TV</span> ; aspects de Brugada, de cardiopathie\n        <span class=\"kw-etio\">ischémique</span>, de préexcitation, de QT long, de CMH ou de repolarisation précoce.</li>\n      </ul>\n\n      <p><strong><span class=\"kw-bio\">ECG</span> percritique — modalités d'enregistrement prolongé</strong> :</p>\n      <table >\n        <thead>\n          <tr><th>Modalité</th><th>Durée</th><th>Indication</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">Holter ECG</span></td>\n            <td><span class=\"kw-chiffre\">24 à 96 h</span></td>\n            <td><span class=\"kw-clinique\">Palpitations</span> <strong>fréquentes</strong> (&gt; 1 par semaine)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">ECG ambulatoire de longue durée</span></td>\n            <td><span class=\"kw-chiffre\">21 jours</span></td>\n            <td><span class=\"kw-clinique\">Palpitations</span> peu fréquentes (&lt; 1 par semaine)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Holter implantable</span> (moniteur <span class=\"kw-bio\">ECG</span> implantable, MEI)</td>\n            <td><span class=\"kw-chiffre\">3 à 5 ans</span></td>\n            <td>Crises <strong>rares</strong> ; pose sous-cutanée parasternale ; <span class=\"kw-def\">suivi</span> possible par télécardiologie</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Montres connectées</span> / smartphone</td>\n            <td>À la demande</td>\n            <td>Tracé piste D<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> l</span>ors des symptômes — aide à la corrélation électro-clinique</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Sur avis spécialisé</strong>, selon les hypothèses diagnostiques :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">épreuve d'effort</span> : intérêt en cas de doute sur un <span class=\"kw-clinique\">angor</span>\n        et pour documenter des <span class=\"kw-clinique\">palpitations</span> survenant à l'effort ;</li>\n        <li><span class=\"kw-imagerie\">étude électrophysiologique endocavitaire</span> : recherche d'une <span class=\"kw-def\">dualité nodale</span> ou\n        d'une voie accessoire — intérêt <strong>diagnostique et thérapeutique</strong> (ablation par radiofréquence) ;</li>\n        <li><span class=\"kw-imagerie\">IRM myocardique</span>, <span class=\"kw-imagerie\">coronarographie</span>,\n        <span class=\"kw-ttt\">tests médicamenteux</span> (isoprénaline, ajmaline), potentiels tardifs ventriculaires\n        (dysplasie arythmogène du VD).</li>\n      </ul>","frequence":0},{"id":"237-5","rang":"A","rubrique":"Étiologies","titre":"Identifier les extrasystoles","contenu":"<p>Les <span class=\"kw-def\">extrasystoles</span> sont des battements <strong>prématurés et\n      ectopiques</strong>, en avance sur les battements « normaux », de <strong>morphologie différente</strong> car\n      naissant en dehors des voies de conduction normales. Elles se classent selon leur origine :</p>\n\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Aspect <span class=\"kw-bio\">ECG</span></th><th>Origine</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>ESA</strong> — extrasystole atriale (supraventriculaire)</td>\n            <td><span class=\"kw-radio\">Onde P' prématurée</span> de morphologie différente, suivie d'un <strong>QRS\n            identique</strong> au QRS de base</td>\n            <td>Oreillettes</td>\n          </tr>\n          <tr>\n            <td><strong>ESV</strong> — extrasystole ventriculaire</td>\n            <td><span class=\"kw-radio\">QRS large prématuré</span>, différent du QRS basal, <strong>sans onde P\n            préalable</strong></td>\n            <td>Ventricules</td>\n          </tr>\n          <tr>\n            <td><strong>ES jonctionnelle</strong> (rare)</td>\n            <td>QRS identique au QRS de base, prématuré, sans onde P préalable</td>\n            <td>Voies de conduction hisiennes</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Caractéristiques à décrire</strong> :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Repos compensateur</span> :</strong> pause totale équivalente à une double période ; les ES\n        <strong>interpolées</strong> n'ont pas de repos compensateur ;</li>\n        <li><strong>Morphologie :</strong> <span class=\"kw-def\">monomorphe</span> (identique) ou\n        <span class=\"kw-def\">polymorphe</span> ;</li>\n        <li><strong>Répartition :</strong> isolée, <span class=\"kw-def\">bigéminée</span> (alternance complexe normal /\n        ES) ou <span class=\"kw-def\">trigéminée</span> (2 complexes normaux pour 1 ES).</li>\n      </ul>\n\n      <p>Les extrasystoles ne sont <strong>pas pathologiques en elles-mêmes</strong>, mais doivent faire rechercher\n      une <span class=\"kw-etio\">cardiopathie sous-jacente</span> ou une <span class=\"kw-etio\">pathologie\n      extracardiaque</span>. Pour l'ESV, un <span class=\"kw-alerte\">couplage court (phénomène R/T)</span> expose à un\n      risque d'<span class=\"kw-alerte\">arythmies ventriculaires létales</span>.</p>\n\n      <div class=\"callout callout-warn\">\n        <strong>Extrasystoles malignes.</strong> Évoquer une malignité si les ES sont\n        <span class=\"kw-alerte\">fréquentes</span>, <span class=\"kw-alerte\">polymorphes</span>, <span class=\"kw-alerte\">en\n        salves</span>, à <span class=\"kw-alerte\">couplage court</span>, déclenchées à l'effort, ou sur\n        <strong><span class=\"kw-def\">terrain</span> cardiopathe</strong> → bilan par <span class=\"kw-imagerie\">ETT</span> +\n        <span class=\"kw-imagerie\">épreuve d'effort</span> + <span class=\"kw-imagerie\">Holter ECG</span>.\n      </div>\n\n      <p><strong>Étiologies favorisantes</strong> : <span class=\"kw-etio\">alcoolisation</span>,\n      <span class=\"kw-etio\">électrocution</span>, <span class=\"kw-etio\">pneumopathie ou néoplasie bronchique</span>,\n      <span class=\"kw-etio\">hyperthyroïdie</span>, <span class=\"kw-etio\">anxiété / dépression</span>,\n      <span class=\"kw-etio\">grossesse</span>, <span class=\"kw-etio\">SAOS</span>.</p>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/237/ecg-extrasystoles-atriales.png\" alt=\"ECG montrant des extrasystoles atriales avec onde P prématurée de morphologie différente\" loading=\"lazy\">\n        <figcaption><strong>Extrasystoles atriales</strong> : onde P' prématurée, de morphologie différente, survenant avant le QRS normalement conduit ; repos compensateur de type post-extrasystolique. Source : fiche source EDN item 237.</figcaption>\n      </figure>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/237/ecg-extrasystoles-ventriculaires.png\" alt=\"ECG montrant des extrasystoles ventriculaires avec QRS larges prématurés et repos compensateur\" loading=\"lazy\">\n        <figcaption><strong>Extrasystoles ventriculaires</strong> : complexes QRS prématurés, larges (≈ 130 ms), différents du QRS basal, sans onde P préalable, suivis d'un repos compensateur. Source : fiche source EDN item 237.</figcaption>\n      </figure>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 242 — <span class=\"kw-def\">Hyperthyroïdie</span></em></p>","frequence":0},{"id":"237-6","rang":"A","rubrique":"Étiologies","titre":"Identifier la tachycardie sinusale","contenu":"<p>La <span class=\"kw-def\">tachycardie sinusale</span> est une accélération de la fréquence sinusale\n      <span class=\"kw-chiffre\">&gt; 100 bpm</span>, à <strong>début et fin progressifs</strong>. Elle est le plus souvent\n      <strong>réactionnelle ou adaptative</strong> : elle répond à un besoin de l'organisme, et n'est donc pas un\n      trouble du rythme primitif.</p>\n\n      <p><strong>Reconnaissance <span class=\"kw-bio\">ECG</span></strong> : la présence du <strong>complexe P-QRS-T</strong> complet affirme le\n      <span class=\"kw-def\">rythme sinusal</span>. Piège : l'<span class=\"kw-alerte\">absence d'onde P visible</span> ne\n      signifie pas qu'il n'y a pas de rythme sinusal — c'est la présence du complexe P-QRS-T qui fait le diagnostic.\n      Un aspect <span class=\"kw-radio\">S1Q3</span> (cœur droit) peut coexister sans remettre en cause le caractère\n      sinusal.</p>\n\n      <table >\n        <thead>\n          <tr><th>Causes cardiaques</th><th>Causes extracardiaques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>\n              <span class=\"kw-etio\">Insuffisance cardiaque</span><br>\n              <span class=\"kw-etio\">Embolie pulmonaire</span><br>\n              <span class=\"kw-etio\">Épanchement péricardique</span>\n            </td>\n            <td>\n              <strong>Hypermétabolisme :</strong> <span class=\"kw-etio\">fièvre</span> ; <span class=\"kw-etio\">sepsis</span> ; <span class=\"kw-etio\">hyperthyroïdie</span> ; <span class=\"kw-etio\">grossesse</span><br>\n              <strong>Hypoxie / bas débit :</strong> <span class=\"kw-etio\">anémie</span> ; <span class=\"kw-etio\">hypovolémie</span> ; <span class=\"kw-etio\">hypoxie</span> ; <span class=\"kw-etio\">hypotension artérielle</span> ; <span class=\"kw-etio\">SAOS</span><br>\n              <strong>Toxiques et médicaments :</strong> <span class=\"kw-etio\">alcool</span> ; <span class=\"kw-ci\">sevrage brutal en bêtabloquant</span> ; <span class=\"kw-ttt\">sevrage</span> alcoolique ; <span class=\"kw-ttt\">sympathomimétiques</span>, <span class=\"kw-ttt\">vasodilatateurs</span>, <span class=\"kw-ttt\">atropiniques</span><br>\n              <strong>Psychogène :</strong> <span class=\"kw-etio\">pathologie psychiatrique</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> La <span class=\"kw-clinique\">tachycardie</span> sinusale <strong>isolée et non adaptative</strong> (sans cause\n        retrouvée) est <span class=\"kw-alerte\">exceptionnelle</span> — devant une <span class=\"kw-clinique\">tachycardie</span> sinusale, il faut donc\n        toujours chercher la cause sous-jacente, cardiaque ou extracardiaque.\n      </div>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/237/ecg-tachycardie-sinusale.png\" alt=\"ECG 12 dérivations d'une tachycardie sinusale avec complexe P-QRS-T conservé\" loading=\"lazy\">\n        <figcaption><strong><span class=\"kw-clinique\">Tachycardie</span> sinusale</strong> : le complexe P-QRS-T est présent, ce qui affirme le rythme sinusal — même lorsque l'onde P est peu visible. Un aspect S1Q3 peut être associé. Source : fiche source EDN item 237.</figcaption>\n      </figure>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/237/schema-tv-tachycardie-sinusale-causes.png\" alt=\"Schéma opposant la tachycardie ventriculaire sur cœur ischémique et la tachycardie sinusale d'origine extracardiaque\" loading=\"lazy\">\n        <figcaption>À gauche, <strong><span class=\"kw-clinique\">tachycardie</span> ventriculaire</strong> sur <span class=\"kw-def\">terrain</span> de cardiopathie <span class=\"kw-etio\">ischémique</span>. À droite, <strong><span class=\"kw-clinique\">tachycardie</span> sinusale</strong> et ses causes extracardiaques : excitants, médicaments, <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-ci\">grossesse</span>, <span class=\"kw-etio\">hyperthyroïdie</span>, <span class=\"kw-clinique\">déshydratation</span>. Source : fiche source EDN item 237.</figcaption>\n      </figure>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 242 — <span class=\"kw-def\">Hyperthyroïdie</span></em></p>","frequence":0},{"id":"237-7","rang":"A","rubrique":"Étiologies","titre":"Identifier les tachycardies jonctionnelles","contenu":"<p>Les <span class=\"kw-def\">tachycardies jonctionnelles</span> naissent au niveau de la jonction\n      atrio-ventriculaire. La forme la plus fréquente est la <span class=\"kw-def\">tachycardie par réentrée\n      intra-nodale</span> (TRIN, ou <strong><span class=\"kw-etio\">maladie de Bouveret</span></strong>) : il existe une <strong>dualité\n      nodale</strong> — une voie lente et une voie rapide au sein du nœud AV — qui permet une <strong>réentrée</strong>\n      auto-entretenue.</p>\n\n      <p><strong><span class=\"kw-def\">Terrain</span></strong> : typiquement le <span class=\"kw-clinique\">sujet jeune</span>, à\n      <strong>cœur normal</strong>.</p>\n\n      <p><strong>Présentation clinique</strong> caractéristique :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">palpitations</span> à <span class=\"kw-clinique\">début et fin brutaux</span>, parfois déclenchées par un changement\n        brusque de position ;</li>\n        <li>durée variable, de quelques minutes à plusieurs heures ;</li>\n        <li><span class=\"kw-clinique\">crise polyurique</span> en fin d'accès — très évocatrice ;</li>\n        <li>bonne <strong>tolérance</strong> hémodynamique en général ;</li>\n        <li>arrêt possible par <span class=\"kw-ttt\">manœuvre vagale</span> ou <span class=\"kw-ttt\">adénosine\n        (Krenosin)</span>.</li>\n      </ul>\n\n      <p><strong><span class=\"kw-bio\">ECG</span></strong> : <span class=\"kw-clinique\">tachycardie</span> <strong>régulière à <span class=\"kw-radio\">QRS fins</span></strong>,\n      fréquence <span class=\"kw-chiffre\">130 à 250 bpm</span>, avec une <span class=\"kw-radio\">onde P' rétrograde</span>\n      (négative dans les dérivations inférieures), proche ou masquée dans le QRS. L'onde P paraît souvent absente\n      alors qu'elle est bien présente.</p>\n\n      <p><strong>Traitement</strong> : <span class=\"kw-ttt\">abstention</span> si crises rares et bien tolérées ;\n      sinon <span class=\"kw-ttt\">ablation de la voie lente</span> par radiofréquence — efficace, avec un faible taux\n      de complication (<span class=\"kw-alerte\">BAV complet</span>).</p>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/237/ecg-tachycardie-jonctionnelle-trin.png\" alt=\"ECG d'une tachycardie jonctionnelle par réentrée intra-nodale à QRS fins réguliers\" loading=\"lazy\">\n        <figcaption><strong><span class=\"kw-clinique\">Tachycardie</span> jonctionnelle par réentrée intra-nodale</strong> : <span class=\"kw-clinique\">tachycardie</span> régulière à QRS fins ; l'onde P semble absente mais elle est rétrograde, masquée par le QRS. Le diagnostic s'appuie aussi sur le <span class=\"kw-def\">terrain</span> (sujet jeune, cœur sain, début et fin brutaux, <span class=\"kw-clinique\">polyurie</span>). Source : fiche source EDN item 237.</figcaption>\n      </figure>","frequence":0},{"id":"237-8","rang":"B","rubrique":"Étiologies","titre":"Identifier le Wolff Parkinson White","contenu":"<p>Dans la population normale, oreillettes et ventricules sont <strong>isolés électriquement</strong> : le seul\n      passage de l'influx se fait par le <span class=\"kw-def\">nœud AV</span> puis le faisceau de His. Le\n      <span class=\"kw-def\">Wolff-Parkinson-White</span> (WPW) correspond à l'existence d'une <strong>voie\n      accessoire — le <span class=\"kw-def\">faisceau de Kent</span></strong>, bandelette musculaire atrio-ventriculaire congénitale — réalisant un <strong>passage direct</strong>\n      de l'influx de l'oreillette vers le ventricule, court-circuitant le nœud AV.</p>\n\n      <p><strong>Signes <span class=\"kw-bio\">ECG</span> de préexcitation</strong> (sur l'<span class=\"kw-bio\">ECG</span> de repos) :</p>\n      <ul>\n        <li><span class=\"kw-radio\">espace PR court</span> <span class=\"kw-chiffre\">&lt; 120 ms</span>, sans retour à la ligne\n        isoélectrique avant le QRS ;</li>\n        <li><span class=\"kw-radio\">onde delta</span> : empâtement de la phase initiale du QRS, aspect triangulaire ;</li>\n        <li><span class=\"kw-radio\">QRS large</span> <span class=\"kw-chiffre\">&gt; 120 ms</span>, du fait de l'onde delta ;</li>\n        <li>troubles de la repolarisation associés.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> La préexcitation <strong>diminue ou disparaît avec l'<span class=\"kw-ttt\">atropine</span></strong> et\n        <strong>augmente avec les manœuvres vagales</strong> (qui bloquent la conduction dans le nœud AV et font donc\n        prédominer la voie accessoire).\n      </div>\n\n      <p><strong>Tachycardies du WPW</strong> :</p>\n      <ul>\n        <li><span class=\"kw-def\">Orthodromique</span> : descente de l'influx par le faisceau de His, remontée par la\n        voie accessoire → <span class=\"kw-radio\">QRS fins</span> + onde P' rétrograde ;</li>\n        <li><span class=\"kw-def\">Antidromique</span> : descente par la voie accessoire, remontée par le His →\n        <span class=\"kw-radio\">QRS larges</span> avec aspect de préexcitation.</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-def\">Pronostic</span>.</strong> Le risque grave du WPW est la <span class=\"kw-alerte\">mort subite</span> : si un\n        épisode de <span class=\"kw-etio\">fibrillation atriale</span> est conduit rapidement aux ventricules par la voie\n        accessoire, on obtient un aspect de <span class=\"kw-alerte\">« super-Wolff »</span> (QRS élargis, irréguliers),\n        pouvant dégénérer en <span class=\"kw-alerte\">fibrillation ventriculaire</span>.\n      </div>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/237/ecg-wolff-parkinson-white.png\" alt=\"ECG 12 dérivations d'un Wolff-Parkinson-White avec PR court et onde delta\" loading=\"lazy\">\n        <figcaption><strong>Wolff-Parkinson-White</strong> : PR court (&lt; 120 ms) et <strong>onde delta</strong> empâtant le début du QRS — l'encart détaille l'onde delta surajoutée au pied du QRS. Source : fiche source EDN item 237.</figcaption>\n      </figure>","frequence":0},{"id":"237-9","rang":"B","rubrique":"Étiologies","titre":"Identifier la névrose cardiaque","contenu":"<p>La <span class=\"kw-def\">névrose cardiaque</span> est un <strong><span class=\"kw-def\">diagnostic d'élimination</span></strong>. Elle est\n      liée à une <span class=\"kw-clinique\">crainte irraisonnée de mourir subitement</span>, et se trouve souvent\n      <strong>auto-entretenue</strong> par des consultations itératives qui renforcent l'anxiété du patient.</p>\n\n      <p><strong>Éléments du diagnostic</strong> :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">ECG normal</span> au moment des <span class=\"kw-clinique\">palpitations</span> — c'est un point clé ;</li>\n        <li>examens cliniques et paracliniques <strong>normaux</strong> ;</li>\n        <li>absence de <span class=\"kw-etio\">pathologie extra-cardiaque</span> ;</li>\n        <li>contexte de <span class=\"kw-etio\">dépression</span> ou d'<span class=\"kw-etio\">anxiété</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Prise en charge.</strong> <span class=\"kw-ttt\">Rassurer le patient</span> est central. Éviter tout\n        <strong>langage inadapté</strong> qui entretiendrait l'angoisse, et <strong>ne pas parler de\n        spasmophilie</strong>.\n      </div>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-clinique\">Tachycardie</span> mal tolérée <span class=\"q\">— mauvaise tolérance hémodynamique</span></strong></p><p><span class=\"kw-ttt\">Cardioversion électrique externe</span> en <span class=\"kw-alerte\">urgence</span></p><ul><li><span class=\"kw-alerte\">FC &gt; 150 bpm</span>, <span class=\"kw-alerte\">hypotension artérielle</span>, <span class=\"kw-alerte\">hypoperfusion périphérique</span></li><li><span class=\"kw-clinique\">Angor</span>, <span class=\"kw-clinique\">insuffisance cardiaque</span>, <span class=\"kw-alerte\">trouble de conscience</span>, <span class=\"kw-clinique\">syncope</span></li></ul><p><strong><span class=\"kw-clinique\">Tachycardie</span> régulière à QRS large</strong></p><p>Se préparer à <span class=\"kw-ttt\">réanimer</span> ; <span class=\"kw-ttt\">cardioversion électrique externe</span> si mauvaise tolérance</p><ul><li><span class=\"kw-alerte\">TV jusqu'à preuve du contraire</span>, surtout sur <span class=\"kw-etio\">cardiopathie ischémique</span> / ATCD d'<span class=\"kw-etio\">IDM</span></li></ul><p><strong>Anomalie de repolarisation</strong></p><p>Prise en charge d'un <span class=\"kw-etio\">syndrome coronarien aigu</span> (item 339)</p><ul><li>Fait craindre un <span class=\"kw-etio\">SCA</span>, surtout si « gêne » thoracique (peut être un <span class=\"kw-clinique\">angor</span> fonctionnel)</li></ul><p><strong>WPW conduisant une FA <span class=\"q\">— « super-Wolff »</span></strong></p><p>Risque de dégénérescence en <span class=\"kw-alerte\">fibrillation ventriculaire</span> et de <span class=\"kw-alerte\">mort subite</span></p><ul><li><span class=\"kw-etio\">FA</span> conduite rapidement aux ventricules par la <span class=\"kw-def\">voie accessoire</span> → QRS élargis, irréguliers</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">FC &gt; 150 bpm</span></li><li><span class=\"kw-alerte\">Hypotension artérielle</span></li><li>Signes d'<span class=\"kw-alerte\">hypoperfusion périphérique</span> : <span class=\"kw-clinique\">TRC allongé</span>, <span class=\"kw-clinique\">marbrures</span></li><li><span class=\"kw-clinique\">Angor</span> (parfois fonctionnel, surtout si <span class=\"kw-chiffre\">FC &gt; 200 bpm</span>)</li><li>Signes d'<span class=\"kw-clinique\">insuffisance cardiaque</span> (<span class=\"kw-clinique\">dyspnée</span>)</li><li><span class=\"kw-alerte\">Signes neurologiques déficitaires</span> (<span class=\"kw-clinique\">infarctus</span> cérébral sur embolie de <span class=\"kw-etio\">FA</span>)</li><li><span class=\"kw-alerte\">Trouble de conscience</span>, <span class=\"kw-clinique\">syncope</span> ou <span class=\"kw-clinique\">lipothymie</span></li><li><span class=\"kw-imagerie\">ECG</span> : <span class=\"kw-alerte\">tachycardie régulière à QRS large</span> (<span class=\"kw-alerte\">TV</span>), <span class=\"kw-alerte\">BAV 2ᵉ ou 3ᵉ degré</span>, <span class=\"kw-alerte\">tachycardie à QRS fins &gt; 150 bpm</span> avec <span class=\"kw-alerte\">signes de gravité</span></li><li>ATCD familial de <span class=\"kw-alerte\">mort subite</span> avant <span class=\"kw-chiffre\">35 ans</span> (<span class=\"kw-etio\">Brugada</span>, <span class=\"kw-etio\">QT long</span>, <span class=\"kw-etio\">dysplasie arythmogène du VD</span>)</li></ul>","principes":"<p>Trois principes pour le <span class=\"kw-def\">diagnostic étiologique</span> : rechercher une <span class=\"kw-etio\">cardiopathie sous-jacente</span> (<span class=\"kw-imagerie\">ETT systématique</span>), rechercher une <span class=\"kw-etio\">cause extracardiaque</span>, et établir la <span class=\"kw-def\">corrélation électro-clinique</span> via un <span class=\"kw-imagerie\">ECG percritique</span>.</p><p><strong>Orientation en crise <span class=\"q\">— blocage du NAV</span></strong></p><p>CI : <span class=\"kw-ci\">asthme</span>, <span class=\"kw-ci\">athérome carotidien / souffle</span>, <span class=\"kw-ci\">HTA ou hypotension non contrôlée</span></p><ul><li><span class=\"kw-ttt\">Manœuvres vagales</span> : Valsalva, compression carotidienne unilatérale, verre d'eau froide</li><li><span class=\"kw-ttt\">Adénosine</span> (ATP) en flash IV si échec des manœuvres vagales</li></ul><p><strong><span class=\"kw-clinique\">Tachycardie</span> jonctionnelle <span class=\"q\">— maladie de Bouveret</span></strong></p><ul><li><span class=\"kw-ttt\">Abstention</span> si crises rares et bien tolérées</li><li>En crise : <span class=\"kw-ttt\">manœuvre vagale</span> ou <span class=\"kw-ttt\">adénosine</span></li><li><span class=\"kw-ttt\">Ablation de la voie lente</span> par radiofréquence (risque faible de <span class=\"kw-alerte\">BAV complet</span>)</li></ul><p><strong><span class=\"kw-clinique\">Tachycardie</span> ventriculaire / mauvaise tolérance</strong></p><ul><li><span class=\"kw-ttt\">Cardioversion électrique externe</span> en <span class=\"kw-alerte\">urgence</span></li></ul><p><strong>Extrasystoles</strong></p><ul><li>Pas pathologiques en elles-mêmes : rechercher une <span class=\"kw-etio\">cardiopathie sous-jacente</span> ou une cause <span class=\"kw-etio\">extracardiaque</span></li><li>Si ESV <span class=\"kw-alerte\">malignes</span> (fréquentes, polymorphes, en salves, couplage court) : bilan <span class=\"kw-imagerie\">ETT</span> + <span class=\"kw-imagerie\">épreuve d'effort</span> + <span class=\"kw-imagerie\">Holter ECG</span></li></ul><p><strong><span class=\"kw-clinique\">Tachycardie</span> sinusale</strong></p><ul><li><span class=\"kw-ttt\">Traiter la cause</span> (réactionnelle dans la quasi-totalité des cas)</li></ul><p><strong>Névrose cardiaque</strong></p><ul><li><span class=\"kw-ttt\">Rassurer le patient</span> ; éviter tout langage anxiogène</li><li>Ne pas parler de <span class=\"kw-ci\">spasmophilie</span></li></ul>"},"liensGlobaux":[{"href":"https://www.sfcardio.fr/page/chapitre-16-item-237-palpitations","label":"SFC — Chapitre 16 item 237 palpitations"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Palpitations avec tachycardie à l'ECG : tolérance hémodynamique ? — ECG percritique obtenu — premier tri = tolérance clinique","detail":"<h4>CAT — <span class=\"kw-clinique\">tachycardie</span> à l'<span class=\"kw-imagerie\">ECG</span> devant des <span class=\"kw-clinique\">palpitations</span> — Tolérance → largeur des QRS → régularité → effet du blocage du NAV</h4>","branches":[{"to":"t-cee","label":"Mauvaise tolérance (FC > 150, hypotension, syncope, angor, IC)","color":"red"},{"to":"q-qrs","label":"Bonne tolérance — analyser l'ECG","color":"blue"}]},{"id":"t-cee","kind":"terminal","label":"Cardioversion électrique externe en urgence","color":"red","detail":"<h4>Indication</h4><ul><li><span class=\"kw-alerte\">Mauvaise tolérance hémodynamique</span> d'une <span class=\"kw-clinique\">tachycardie</span>, quelle qu'en soit l'origine</li></ul><h4>Signes de mauvaise tolérance</h4><ul><li><span class=\"kw-alerte\">FC &gt; 150 bpm</span>, <span class=\"kw-alerte\">hypotension artérielle</span></li><li><span class=\"kw-alerte\">Hypoperfusion périphérique</span> : <span class=\"kw-clinique\">TRC allongé</span>, <span class=\"kw-clinique\">marbrures</span></li><li><span class=\"kw-clinique\">Angor</span>, <span class=\"kw-clinique\">insuffisance cardiaque</span>, <span class=\"kw-alerte\">trouble de conscience</span>, <span class=\"kw-clinique\">syncope</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Cardioversion électrique externe</span> sans délai ; se préparer à <span class=\"kw-ttt\">réanimer</span></li></ul>"},{"id":"q-qrs","kind":"decision","label":"Largeur des QRS ? — Seuil 120 ms","branches":[{"to":"t-tv","label":"QRS larges (> 120 ms), réguliers","color":"red"},{"to":"q-regularite","label":"QRS fins (< 120 ms)","color":"blue"}]},{"id":"t-tv","kind":"terminal","label":"Tachycardie ventriculaire (jusqu'à preuve du contraire)","color":"red","detail":"<h4>Reconnaissance <span class=\"kw-imagerie\">ECG</span></h4><ul><li><span class=\"kw-clinique\">Tachycardie régulière à QRS larges</span> ; <span class=\"kw-radio\">dissociation atrio-ventriculaire</span> ; <span class=\"kw-radio\">complexe de fusion</span></li></ul><h4><span class=\"kw-def\">Terrain</span></h4><ul><li>Évoquer en priorité sur <span class=\"kw-etio\">cardiopathie ischémique</span> / ATCD d'<span class=\"kw-etio\">IDM</span> (zone de <span class=\"kw-clinique\">nécrose</span> → fibrose arythmogène)</li></ul><h4>Effet du blocage du NAV</h4><ul><li><span class=\"kw-ttt\">Manœuvres vagales</span> / <span class=\"kw-ttt\">adénosine</span> : aucun effet sur la fréquence ventriculaire</li></ul><h4>Conduite</h4><ul><li>Se préparer à <span class=\"kw-ttt\">réanimer</span> ; <span class=\"kw-ttt\">cardioversion électrique externe</span> si mauvaise tolérance</li></ul>"},{"id":"q-regularite","kind":"decision","label":"Rythme régulier ou irrégulier ? — La FA est la seule cause de tachycardie réellement irrégulière","branches":[{"to":"t-fa","label":"Irrégulier","color":"amber"},{"to":"q-nav","label":"Régulier","color":"blue"}]},{"id":"t-fa","kind":"terminal","label":"Fibrillation atriale","color":"amber","detail":"<h4>Reconnaissance <span class=\"kw-imagerie\">ECG</span></h4><ul><li><span class=\"kw-clinique\">Tachycardie irrégulière</span> ; <span class=\"kw-radio\">trémulation anarchique de la ligne de base</span> (absence d'onde P organisée)</li></ul><h4>Repère</h4><ul><li>Seule cause de <span class=\"kw-clinique\">tachycardie réellement irrégulière</span> ; risque <span class=\"kw-etio\">embolique</span> (<span class=\"kw-alerte\">infarctus cérébral</span>)</li></ul>"},{"id":"q-nav","kind":"decision","label":"Effet du blocage du NAV (manœuvres vagales / adénosine) ? — Bloquer le NAV ralentit le ventricule et démasque l'activité atriale","branches":[{"to":"t-tj","label":"Interruption brutale de la tachycardie","color":"green"},{"to":"t-tsv","label":"Ralentissement + démasquage de l'activité atriale","color":"amber"},{"to":"t-sinusale","label":"Complexe P-QRS-T conservé, début/fin progressifs","color":"blue"}]},{"id":"t-tj","kind":"terminal","label":"Tachycardie jonctionnelle (Bouveret)","color":"green","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li><span class=\"kw-clinique\">Sujet jeune</span>, à cœur sain</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Début et fin brutaux</span> ; <span class=\"kw-clinique\">crise polyurique</span> finale très évocatrice</li></ul><h4><span class=\"kw-imagerie\">ECG</span></h4><ul><li><span class=\"kw-clinique\">Régulière à QRS fins</span>, <span class=\"kw-chiffre\">130 à 250 bpm</span> ; <span class=\"kw-radio\">onde P' rétrograde</span> masquée dans le QRS</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Abstention</span> si rare et bien tolérée ; <span class=\"kw-ttt\">manœuvre vagale</span> / <span class=\"kw-ttt\">adénosine</span> en crise ; <span class=\"kw-ttt\">ablation de la voie lente</span> par radiofréquence</li></ul>"},{"id":"t-tsv","kind":"terminal","label":"TSV : flutter ou tachycardie atriale focale","color":"amber","detail":"<h4><span class=\"kw-clinique\">Flutter</span> atrial</h4><ul><li><span class=\"kw-radio\">Ondes F en toit d'usine</span> ; le plus souvent régulier</li></ul><h4><span class=\"kw-clinique\">Tachycardie</span> atriale focale</h4><ul><li><span class=\"kw-radio\">Ondes P' avec retour à la ligne isoélectrique</span></li></ul><h4>Mécanisme du test</h4><ul><li>Le <span class=\"kw-ttt\">blocage du NAV</span> ralentit le ventricule sans réduire l'<span class=\"kw-clinique\">arythmie</span>, démasquant l'activité atriale</li></ul>"},{"id":"t-sinusale","kind":"terminal","label":"Tachycardie sinusale","color":"blue","detail":"<h4>Reconnaissance <span class=\"kw-imagerie\">ECG</span></h4><ul><li>Présence du <span class=\"kw-radio\">complexe P-QRS-T</span> = affirme le <span class=\"kw-def\">rythme sinusal</span> ; <span class=\"kw-chiffre\">&gt; 100 bpm</span>, début et fin progressifs</li></ul><h4>Le plus souvent réactionnelle</h4><ul><li>Causes cardiaques (<span class=\"kw-etio\">insuffisance cardiaque</span>, <span class=\"kw-etio\">embolie pulmonaire</span>, <span class=\"kw-etio\">épanchement péricardique</span>) ou extracardiaques (<span class=\"kw-etio\">fièvre</span>, <span class=\"kw-etio\">hyperthyroïdie</span>, <span class=\"kw-etio\">anémie</span>, <span class=\"kw-etio\">hypovolémie</span>, excitants)</li></ul><h4>Piège + conduite</h4><ul><li>Une <span class=\"kw-clinique\">tachycardie</span> sinusale <span class=\"kw-alerte\">isolée non adaptative</span> est exceptionnelle → toujours <span class=\"kw-ttt\">chercher et traiter la cause</span></li></ul>"}]},"cards":[{"i":"7e398f11a5a9","n":237,"o":"237-1","u":"Définition","t":"Connaître la définition des palpitations","q":"Quelle est la définition des palpitations en contexte médical ?","a":"<p>Les palpitations sont la perception <strong>anormale</strong> d'un rythme ou de battements cardiaques, qu'ils soient normaux ou anormaux. Le patient décrit souvent une sensation de « cœur qui se débat » dans la poitrine, battant <strong>trop fort</strong>, <strong>trop vite</strong> ou de façon <strong>irrégulière</strong>.</p>"},{"i":"8e13b881a076","n":237,"o":"237-1","u":"Définition","t":"Connaître la définition des palpitations","q":"Quelles sont les caractéristiques générales des palpitations, au-delà de la définition purement rythmique ?","a":"<p>Les palpitations sont un symptôme <strong>subjectif</strong>. Elles ne témoignent pas systématiquement d'une anomalie cardiaque sous-jacente et sont le plus souvent <strong>anxiogènes</strong>. La localisation ressentie par le patient (région latérocervicale, précordium, régions latérothoracique ou médiothoracique) n'est pas spécifique.</p>"},{"i":"b9aae633c5d2","n":237,"o":"237-1","u":"Définition","t":"Connaître la définition des palpitations","q":"Quelle est la particularité rythmique de la fibrillation atriale par rapport au flutter atrial ?","a":"<p>La <strong>fibrillation atriale (FA)</strong> est la seule cause de tachycardie réellement <strong>irrégulière</strong>. Le <strong>flutter atrial</strong>, en revanche, est le plus souvent <strong>régulier</strong>.</p>"},{"i":"dee89a605a7b","n":237,"o":"237-1","u":"Définition","t":"Connaître la définition des palpitations","q":"Quelles sont les quatre familles de causes de palpitations à connaître ?","a":"<ul>\n<li>La <strong>fibrillation atriale (FA)</strong></li>\n<li>Le <strong>flutter atrial</strong></li>\n<li>Les <strong>tachycardies jonctionnelles</strong></li>\n<li>Les <strong>autres troubles du rythme</strong></li>\n</ul>"},{"i":"1aa169e9940a","n":237,"o":"237-2","u":"Identifier une urgence","t":"Connaître les signes de gravité et diagnostiques ECG urgents","q":"Comment distinguer une tachycardie ventriculaire (TV) d'une tachycardie supraventriculaire (TSV) avec bloc de branche sur un ECG, en cas de tachycardie régulière à QRS larges ?","a":"<p>Une <strong>tachycardie ventriculaire (TV)</strong> se caractérise par :</p><ul><li>Une <strong>tachycardie régulière à QRS larges</strong>.</li><li>Une <strong>dissociation atrio-ventriculaire</strong> (aucune onde P n'est suivie d'un QRS, il n'y a pas de complexe P-QRS-T cohérent).</li><li>La présence possible d'un <strong>complexe de fusion</strong>.</li></ul><p>En l'absence de ces signes formels de TV, une tachycardie régulière à QRS larges peut également correspondre à une <strong>tachycardie supraventriculaire (TSV)</strong> avec bloc de branche ou préexcitation, mais il est crucial de considérer une TV jusqu'à preuve du contraire.</p>"},{"i":"574e675e8913","n":237,"o":"237-2","u":"Identifier une urgence","t":"Connaître les signes de gravité et diagnostiques ECG urgents","q":"Quels sont les éléments de l'anamnèse qui doivent alerter devant des palpitations et faire craindre une situation à risque ?","a":"<p>Devant des palpitations, les éléments d'anamnèse alarmants incluent :</p><ul><li>Des <strong>antécédents personnels</strong> : infarctus du myocarde, HTA, autre cardiopathie, trouble du rythme connu, appareillage par stimulateur ou défibrillateur.</li><li>Des <strong>antécédents familiaux de mort subite</strong>, surtout chez l'enfant ou l'adolescent (avant 35 ans), évoquant une cause génétique (syndrome de Brugada, QT long, dysplasie arythmogène du ventricule droit) et imposant un arbre généalogique.</li><li>La <strong>prise d'un antiarythmique</strong> ou d'un traitement allongeant le QT.</li></ul>"},{"i":"66c2a8bb7b69","n":237,"o":"237-2","u":"Identifier une urgence","t":"Connaître les signes de gravité et diagnostiques ECG urgents","q":"Quels sont les diagnostics urgents à identifier sur l'électrocardiogramme (ECG) en cas de palpitations, même si l'ECG initial est le plus souvent normal en dehors de la crise ?","a":"<p>Les diagnostics urgents à identifier sur l'ECG en cas de palpitations sont :</p><ul><li>Une <strong>tachycardie régulière à QRS large</strong>, qui doit être considérée comme une tachycardie ventriculaire (TV) jusqu'à preuve du contraire et impose une préparation à la réanimation.</li><li>Une <strong>anomalie de repolarisation</strong> faisant craindre un syndrome coronarien aigu (SCA), surtout en cas de gêne thoracique.</li><li>Un <strong>bloc auriculo-ventriculaire (BAV) du 2<sup>e</sup> ou du 3<sup>e</sup> degré</strong>.</li><li>Une <strong>tachycardie à QRS fins supérieure à 150 bpm</strong>, associée à des signes cliniques de gravité.</li></ul>"},{"i":"81fb23ea70d1","n":237,"o":"237-2","u":"Identifier une urgence","t":"Connaître les signes de gravité et diagnostiques ECG urgents","q":"Quels sont les signes cliniques de gravité des palpitations, traduisant une mauvaise tolérance hémodynamique ?","a":"<p>Les signes cliniques de gravité devant des palpitations sont :</p><ul><li>Une <strong>fréquence cardiaque supérieure à 150 bpm</strong> (battements par minute).</li><li>Une <strong>hypotension artérielle</strong>.</li><li>Des <strong>signes d'hypoperfusion périphérique</strong> : temps de recoloration capillaire (TRC) allongé, marbrures.</li><li>Un <strong>angor</strong> (douleur thoracique de type angine de poitrine), parfois fonctionnel si la fréquence cardiaque est supérieure à 200 bpm.</li><li>Des <strong>signes d'insuffisance cardiaque</strong> (ex: dyspnée).</li><li>Des <strong>signes neurologiques déficitaires</strong> évoquant un infarctus cérébral (embolie sur fibrillation atriale).</li><li>Un <strong>trouble de conscience</strong>.</li><li>Une <strong>syncope</strong> ou une lipothymie.</li></ul>"},{"i":"b8b942f6c5bf","n":237,"o":"237-2","u":"Identifier une urgence","t":"Connaître les signes de gravité et diagnostiques ECG urgents","q":"Quel est le traitement d'urgence en cas de tachycardie avec mauvaise tolérance hémodynamique ?","a":"<p>En cas de tachycardie avec mauvaise tolérance hémodynamique, le traitement est la <strong>cardioversion électrique externe en urgence</strong>.</p>"},{"i":"002314138bf3","n":237,"o":"237-3","u":"Diagnostic positif","t":"Connaître la notion de parallélisme électro-clinique","q":"Quelles sont les contre-indications des manœuvres de blocage du NAV et de l'adénosine ?","a":"<ul><li>La <strong>compression carotidienne</strong> est contre-indiquée en cas d'<strong>athérome carotidien</strong> ou de <strong>souffle</strong>.</li><li>L'<strong>adénosine</strong> est contre-indiquée en cas d'<strong>asthme</strong> (risque de bronchospasme intense, même chez un non-asthmatique) et d'<strong>HTA ou hypotension non contrôlée</strong>.</li><li>La compression oculaire bilatérale n'est plus recommandée.</li></ul>"},{"i":"3321fcfc3d34","n":237,"o":"237-3","u":"Diagnostic positif","t":"Connaître la notion de parallélisme électro-clinique","q":"Comment les manœuvres de blocage du nœud atrio-ventriculaire (NAV) peuvent-elles aider au diagnostic d'une tachycardie ?","a":"<p>En cas de tachycardie en crise, le blocage du NAV (par <strong>manœuvres vagales</strong> ou <strong>adénosine en flash IV</strong>) permet de ralentir la cadence ventriculaire et de <strong>démasquer l'activité atriale</strong>, orientant ainsi l'étiologie :</p><ul><li><strong>Interruption brutale</strong> de la tachycardie : très en faveur d'une tachycardie jonctionnelle (réentrée intranodale ou voie accessoire).</li><li><strong>Ralentissement avec démasquage de l'activité atriale</strong> : très en faveur d'une tachycardie supraventriculaire (TSV).</li><li><strong>Aucun effet sur la fréquence ventriculaire</strong> : très en faveur d'une tachycardie ventriculaire.</li></ul>"},{"i":"6a8284b81d72","n":237,"o":"237-3","u":"Diagnostic positif","t":"Connaître la notion de parallélisme électro-clinique","q":"Qu'est-ce que le parallélisme électro-clinique dans le cadre des palpitations ?","a":"<p>Le parallélisme électro-clinique, ou corrélation électro-clinique, désigne la <strong>concordance entre les symptômes ressentis par le patient</strong> (les palpitations) et les <strong>anomalies enregistrées sur l'électrocardiogramme</strong> (ECG).</p>"},{"i":"e769f129d7d1","n":237,"o":"237-3","u":"Diagnostic positif","t":"Connaître la notion de parallélisme électro-clinique","q":"Quels sont les différents moyens d'enregistrement de l'ECG pour mettre en évidence un parallélisme électro-clinique ?","a":"<ul><li><strong>ECG 12 dérivations de repos</strong> : enregistrement de courte durée (~10 secondes).</li><li><strong>Holter ECG</strong> : enregistrement sur une durée de <strong>24 à 96 heures</strong>.</li><li><strong>Holter implantable</strong> : surveillance prolongée sur <strong>3 à 5 ans</strong>.</ul><p>Plus la durée d'enregistrement est longue, plus la sensibilité de détection est élevée, permettant de capter des arythmies paroxystiques rares.</p>"},{"i":"1b2363dc1e70","n":237,"o":"237-5","u":"Étiologies","t":"Identifier les extrasystoles","q":"Dans quels cas les extrasystoles doivent-elles faire rechercher une cardiopathie sous-jacente ou sont-elles considérées comme malignes ?","a":"<p>Les extrasystoles en elles-mêmes ne sont pas pathologiques, mais elles doivent faire rechercher une cardiopathie sous-jacente ou une pathologie extracardiaque. Elles sont considérées comme « malignes » et nécessitent un bilan (ETT, épreuve d'effort, Holter ECG) si elles sont : <strong>fréquentes</strong>, <strong>polymorphes</strong>, en <strong>salves</strong>, à <strong>couplage court</strong> (phénomène R/T, surtout pour les ESV, avec risque d'arythmies ventriculaires létales), <strong>déclenchées à l'effort</strong>, ou sur un <strong>terrain cardiopathe</strong>.</p>"},{"i":"3706ccda0906","n":237,"o":"237-5","u":"Étiologies","t":"Identifier les extrasystoles","q":"Quelles sont les étiologies favorisantes des extrasystoles ?","a":"<p>Les étiologies favorisantes des extrasystoles incluent : l'<strong>alcoolisation</strong>, l'<strong>électrocution</strong>, les <strong>pneumopathies ou néoplasies bronchiques</strong>, l'<strong>hyperthyroïdie</strong>, l'<strong>anxiété/dépression</strong>, la <strong>grossesse</strong> et le <strong>syndrome d'apnées obstructives du sommeil (SAOS)</strong>.</p>"},{"i":"4451da31c652","n":237,"o":"237-5","u":"Étiologies","t":"Identifier les extrasystoles","q":"Comment les extrasystoles sont-elles classées selon leur origine et comment se manifestent-elles à l'ECG pour les extrasystoles atriales et ventriculaires ?","a":"<ul><li><strong>Extrasystole atriale (ESA)</strong> : Elle naît dans les <strong>oreillettes</strong>. À l'ECG, on observe une <strong>onde P' prématurée de morphologie différente</strong>, suivie d'un QRS identique au QRS de base.</li><li><strong>Extrasystole ventriculaire (ESV)</strong> : Elle naît dans les <strong>ventricules</strong>. À l'ECG, on observe un <strong>QRS large prématuré</strong>, différent du QRS basal, sans onde P préalable.</li><li><strong>Extrasystole jonctionnelle</strong> (rare) : Elle naît dans les voies de conduction hisiennes. À l'ECG, le QRS est identique au QRS de base, prématuré, sans onde P préalable.</li></ul>"},{"i":"94e3b9e4edc9","n":237,"o":"237-5","u":"Étiologies","t":"Identifier les extrasystoles","q":"Quelle est la définition générale d'une extrasystole ?","a":"<p>Une extrasystole est un battement <strong>prématuré et ectopique</strong>, qui survient en avance sur les battements normaux. Sa morphologie est différente car elle naît en dehors des voies de conduction normales.</p>"},{"i":"e78aa513065a","n":237,"o":"237-5","u":"Étiologies","t":"Identifier les extrasystoles","q":"Quelles sont les caractéristiques des extrasystoles à décrire à l'ECG ?","a":"<ul><li>Le <strong>repos compensateur</strong> : pause totale équivalente à une double période (les ES interpolées n'ont pas de repos compensateur).</li><li>La <strong>morphologie</strong> : monomorphe (identique) ou polymorphe.</li><li>La <strong>répartition</strong> : isolée, bigéminée (alternance complexe normal / ES) ou trigéminée (2 complexes normaux pour 1 ES).</li></ul>"},{"i":"72ca1d0975fc","n":237,"o":"237-6","u":"Étiologies","t":"Identifier la tachycardie sinusale","q":"Quelles sont les principales causes de tachycardie sinusale, qu'elles soient cardiaques ou extracardiaques ?","a":"<p>Les causes de tachycardie sinusale sont nombreuses :</p><ul><li><strong>Causes cardiaques :</strong> <ul><li>Insuffisance cardiaque</li><li>Épanchement péricardique</li><li>Embolie pulmonaire</li></ul></li><li><strong>Causes extracardiaques :</strong><ul><li><strong>Hypermétabolisme :</strong> fièvre, sepsis, hyperthyroïdie, grossesse</li><li><strong>Hypoxie / bas débit :</strong> anémie, hypovolémie, hypoxie, hypotension artérielle, syndrome d'apnées obstructives du sommeil (SAOS)</li><li><strong>Toxiques et médicaments :</strong> alcool, sevrage brutal en bêtabloquant, sevrage alcoolique, sympathomimétiques, vasodilatateurs, atropiniques</li><li><strong>Psychogène :</strong> pathologie psychiatrique</li></ul></li></ul>"},{"i":"afefad726a5c","n":237,"o":"237-6","u":"Étiologies","t":"Identifier la tachycardie sinusale","q":"Comment reconnaît-on une tachycardie sinusale à l'électrocardiogramme (ECG) ?","a":"<p>À l'ECG, la tachycardie sinusale est affirmée par la présence d'un <strong>complexe P-QRS-T complet</strong>. Un <strong>piège classique</strong> est que l'absence d'onde P visible ne signifie pas l'absence de rythme sinusal ; c'est bien la présence de l'ensemble P-QRS-T qui permet le diagnostic. On peut aussi parfois observer un aspect <strong>S1Q3</strong> (témoignant d'un cœur droit) qui n'exclut pas le caractère sinusal.</p>"},{"i":"cad97f7d9bd0","n":237,"o":"237-6","u":"Étiologies","t":"Identifier la tachycardie sinusale","q":"Comment définit-on une tachycardie sinusale et quelles en sont les caractéristiques principales ?","a":"<p>La tachycardie sinusale est une accélération de la fréquence sinusale à <strong>plus de 100 battements par minute (bpm)</strong>. Elle se caractérise par un <strong>début et une fin progressifs</strong>. Elle est le plus souvent <strong>réactionnelle ou adaptative</strong>, répondant à un besoin de l'organisme et n'étant donc pas un trouble du rythme primitif.</p>"},{"i":"d11c7a2cc447","n":237,"o":"237-6","u":"Étiologies","t":"Identifier la tachycardie sinusale","q":"Quel est le piège diagnostique majeur concernant la recherche étiologique d'une tachycardie sinusale ?","a":"<p>Le piège est de penser qu'une tachycardie sinusale puisse être isolée et non adaptative. La <strong>tachycardie sinusale isolée sans cause retrouvée est exceptionnelle</strong>. Il faut donc toujours rechercher une <strong>cause sous-jacente</strong>, qu'elle soit cardiaque ou extracardiaque, devant toute tachycardie sinusale.</p>"},{"i":"19cdd8b30f25","n":237,"o":"237-7","u":"Étiologies","t":"Identifier les tachycardies jonctionnelles","q":"Quelles sont les options thérapeutiques pour la tachycardie par réentrée intra-nodale (TRIN) ?","a":"<ul><li><strong>Abstention</strong> si les crises sont rares et bien tolérées.</li><li>En cas de crises invalidantes, le traitement de choix est l'<strong>ablation de la voie lente par radiofréquence</strong>, qui est efficace avec un faible taux de complications (ex: BAV complet).</li><li>L'arrêt de crise peut être obtenu par les <strong>manœuvres vagales</strong> ou l'<strong>adénosine (Krenosin)</strong>.</li></ul>"},{"i":"2f1c20e3fd3c","n":237,"o":"237-7","u":"Étiologies","t":"Identifier les tachycardies jonctionnelles","q":"Quelle est l'origine des tachycardies jonctionnelles et quelle est leur forme la plus fréquente ?","a":"<p>Les tachycardies jonctionnelles naissent au niveau de la <strong>jonction atrio-ventriculaire</strong>. La forme la plus fréquente est la <strong>tachycardie par réentrée intra-nodale (TRIN)</strong>, ou maladie de Bouveret.</p>"},{"i":"65cfed07578a","n":237,"o":"237-7","u":"Étiologies","t":"Identifier les tachycardies jonctionnelles","q":"Quels sont les signes électrocardiographiques d'une tachycardie par réentrée intra-nodale (TRIN) ?","a":"<ul><li><strong>Tachycardie régulière à QRS fins</strong>.</li><li>Fréquence cardiaque entre <strong>130 et 250 bpm</strong>.</li><li>Présence d'une <strong>onde P' rétrograde</strong> (négative dans les dérivations inférieures), qui est proche ou masquée dans le QRS (elle peut sembler absente).</li></ul>"},{"i":"a0dc90608985","n":237,"o":"237-7","u":"Étiologies","t":"Identifier les tachycardies jonctionnelles","q":"Comment se présente cliniquement une tachycardie par réentrée intra-nodale (TRIN) ?","a":"<ul><li><strong>Palpitations à début et fin brutaux</strong>, parfois déclenchées par un changement de position.</li><li>Durée variable, de quelques minutes à plusieurs heures.</li><li><strong>Crise polyurique</strong> en fin d'accès, très évocatrice.</li><li>Généralement une <strong>bonne tolérance hémodynamique</strong>.</li><li>Terrain : <strong>sujet jeune</strong>, à <strong>cœur normal</strong>.</li></ul>"},{"i":"d3976bea8260","n":237,"o":"237-7","u":"Étiologies","t":"Identifier les tachycardies jonctionnelles","q":"Quelle est la physiopathologie de la tachycardie par réentrée intra-nodale (TRIN) ?","a":"<p>La TRIN est due à l'existence d'une <strong>dualité nodale</strong> au sein du nœud atrio-ventriculaire, comportant une voie lente et une voie rapide. Cette dualité permet une <strong>réentrée auto-entretenue</strong>.</p>"}]};